int copy_auth_to_skb(struct xfrm_algo_auth *auth, struct sk_buff *skb) {
    struct nlattr *nla;

    nla = skb_reserve(skb, nla_total_size(sizeof(*auth)));
    if (!nla)
        return -EMSGSIZE;

    nla->nla_type = XFRMA_ALG_AUTH;
    nla->nla_len = nla_total_size(sizeof(*auth));

    struct xfrm_algo_auth *nla_auth = nla_data(nla);
    strcpy(nla_auth->alg_name, auth->alg_name);
    strcpy(nla_auth->alg_key, auth->alg_key);
    nla_auth->alg_key_len = auth->alg_key_len;

    return 0;
}

